    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function toLines(b) {
    const pre = 'sensor,run=' + b.run + ',stream=' + b.stream + ' ';
    const n = b.t.length, nf = b.fields.length, L = new Array(n);
    for (let i = 0; i < n; i++) {
